 private void target(Object entity,Campaign.Zone z,String role){if(!Reflect.is(entity,"net.minecraft.entity.EntityLiving"))return;Object at=point(z,role,false);if(at!=null)Reflect.call(Reflect.call(entity,"getNavigator/func_70661_as"),"tryMoveToXYZ/func_75492_a",Reflect.x(at)+.5,(double)Reflect.y(at),Reflect.z(at)+.5,1d);}
 private static void particles(Object w,Object type,double x,double y,double z,int count){Reflect.call(w,"spawnParticle/func_175739_a",type,x,y,z,count,.3,.15,.3,.01,new int[0]);}
 public Object point(Campaign.Zone z,String role,boolean spawn){Object w=world(z.dimension);if(w==null)return null;int offset=spawn?24:role.equals("distraction")?20:12;int dx=role.equals("flank")?offset:role.equals("rear")?-offset:0,dz=role.equals("flank")||role.equals("rear")?0:offset;
  for(int attempt=0;attempt<12;attempt++){int x=z.x+dx+(attempt%3-1)*3,zz=z.z+dz+(attempt/3-1)*3;Object seed=Reflect.pos(x,z.y,zz);if(!Reflect.loaded(w,seed))continue;for(int dy=12;dy>=-12;dy--){int y=Math.max(1,Math.min(253,z.y+dy));Object feet=Reflect.pos(x,y,zz),head=Reflect.pos(x,y+1,zz),ground=Reflect.pos(x,y-1,zz);if(!(Boolean)Reflect.call(w,"isAirBlock/func_175623_d",feet)||!(Boolean)Reflect.call(w,"isAirBlock/func_175623_d",head))continue;Object state=Reflect.state(w,ground);if(!(Boolean)Reflect.call(state,"isFullCube/func_185913_b"))continue;if(spawn){boolean visible=false;for(Object p:players())if(Reflect.dimension(Reflect.world(p))==z.dimension){double px=((Number)Reflect.get(p,"posX/field_70165_t")).doubleValue()-x,pz=((Number)Reflect.get(p,"posZ/field_70161_v")).doubleValue()-zz;if(px*px+pz*pz<400)visible=true;}if(visible||runtime.protectedAt(w,feet))continue;}return feet;}}return null;
 }
 public boolean phaseAllowed(Object entity){Integer phase=phases.get(Reflect.entityId(entity));return phase==null||runtime.campaign.phase>=phase;}
 public void scan(){if(scanZone==null){for(Campaign.Zone z:runtime.campaign.zones)if(runtime.campaign.activeTicks-z.scannedAt>=runtime.settings.scanTicks){Object w=world(z.dimension);if(w==null||!Reflect.loaded(w,Reflect.pos(z.x,z.y,z.z))){z.complete=false;continue;}if(!Reflect.blockId(w,Reflect.pos(z.x,z.y,z.z)).equals("dead_earth:zone_relay")){z.complete=false;continue;}scanZone=z;z.scanError="";scanOK=true;scanTiles=new ArrayList<Object>();for(int cx=(z.x>>4)-runtime.settings.zoneRadiusChunks;cx<=(z.x>>4)+runtime.settings.zoneRadiusChunks;cx++)for(int cz=(z.z>>4)-runtime.settings.zoneRadiusChunks;cz<=(z.z>>4)+runtime.settings.zoneRadiusChunks;cz++){Object seed=Reflect.pos(cx*16,64,cz*16);if(!Reflect.loaded(w,seed)){scanOK=false;scanZone.scanError="unloaded_chunk:"+cx+":"+cz;continue;}Object chunk=Reflect.call(w,"getChunkFromChunkCoords/func_72964_e",cx,cz);Map<?,?> tiles=(Map<?,?>)Reflect.call(chunk,"getTileEntityMap/func_177434_r");for(Object tile:tiles.values()){scanTiles.add(tile);if(scanTiles.size()>runtime.settings.maximumZoneTiles)break;}if(scanTiles.size()>runtime.settings.maximumZoneTiles)break;}scanIndex=0;stock=armed=empty=0;ignored=unknown=0;scanOK=scanOK&&scanTiles.size()<=runtime.settings.maximumZoneTiles;break;}}
  if(scanZone==null)return;
  int processed=0,slots=0;
  while((inventoryCursor!=null||scanIndex<scanTiles.size())&&slots<runtime.settings.inventorySlotsPerTick){
   if(inventoryCursor!=null){
    try{inventoryCursor.verify();InventoryValuation.Entry entry=inventoryCursor.next();if(entry!=null){slots++;if(entry.stack!=null&&entry.count>0)add(entry.stack,entry.count);}if(inventoryCursor.done())inventoryCursor=null;}
    catch(RuntimeException error){scanOK=false;scanZone.scanError=error.getMessage();inventoryCursor=null;}
    continue;
   }
   if(processed++>=runtime.settings.tilesPerTick||scanIndex>=runtime.settings.maximumZoneTiles)break;
   Object tile=scanTiles.get(scanIndex++);try{stock(tile);}catch(RuntimeException error){scanOK=false;scanZone.scanError=error.getMessage();}
  }
  if(inventoryCursor==null&&(scanIndex>=scanTiles.size()||scanIndex>=runtime.settings.maximumZoneTiles)){
   scanZone.resourceEmc=stock;scanZone.armedRank=armed;scanZone.emptyRank=empty;scanZone.ignoredLootContainers=ignored;scanZone.unknownTurrets=unknown;
   scanZone.value=stock*runtime.settings.resourceCoefficient-armed+empty;scanZone.scannedAt=runtime.campaign.activeTicks;scanZone.complete=scanOK&&unknown==0;scanZone=null;scanTiles=null;
  }
 }
 private void stock(Object tile){Object level=Reflect.call(tile,"getWorld/func_145831_w"),position=Reflect.call(tile,"getPos/func_174877_v");if(!Reflect.loaded(level,position)||Reflect.call(level,"getTileEntity/func_175625_s",position)!=tile)throw new IllegalStateException("Stale scan tile");String id=Reflect.blockId(Reflect.call(tile,"getWorld/func_145831_w"),Reflect.call(tile,"getPos/func_174877_v"));if(tile.getClass().getName().startsWith("com.hbm.tileentity.turret.")){Integer rank=runtime.settings.turretRanks.get(id);if(rank==null){unknown++;return;}boolean power=(Boolean)Reflect.call(tile,"hasPower"),on=(Boolean)Reflect.call(tile,"isOn");if(on&&power&&Reflect.call(tile,"getFirstConfigLoaded")!=null)armed+=rank;else empty+=rank;return;}
  if(Reflect.is(tile,"net.minecraft.tileentity.TileEntityLockableLoot")&&Reflect.get(tile,"lootTable/field_184284_m")!=null){ignored++;return;}
  inventoryCursor=InventoryValuation.open(tile,runtime.settings);if(inventoryCursor.done())inventoryCursor=null;
 }
 private void add(Object stack,long count){if((Boolean)Reflect.call(stack,"isEmpty/func_190926_b"))return;String id=Reflect.call(Reflect.call(stack,"getItem/func_77973_b"),"getRegistryName").toString();int meta=((Number)Reflect.call(stack,"getMetadata/func_77960_j")).intValue();Long price=runtime.settings.resourcePrices.get(id+":"+meta);if(price==null)price=runtime.settings.resourcePrices.get(id);if(price==null)return;stock=Math.addExact(stock,Math.multiplyExact(price,count));}
